using System.ComponentModel.DataAnnotations;namespace PizzaSatinAlmaYonetimi.Web.Models;
public sealed record BildirimSatiri(int BildirimId,string Baslik,string Mesaj,string OkunmaDurumu,DateTime OlusturmaTarihi,DateTime? OkunmaTarihi,string? HedefUrl=null);
public sealed class BildirimViewModel{public IReadOnlyList<BildirimSatiri>Bildirimler{get;init;}=[];public int OkunmamisSayisi{get;init;}public int OkunmusSayisi=>Bildirimler.Count-OkunmamisSayisi;}
public sealed class ProfilModel{[Required][StringLength(100)]public string AdSoyad{get;set;}=string.Empty;[Required][EmailAddress(ErrorMessage="Geçerli bir e-posta adresi girin.")][StringLength(254)]public string Eposta{get;set;}=string.Empty;public string KullaniciAdi{get;set;}=string.Empty;public string RolAdi{get;set;}=string.Empty;}
public sealed class SifreDegistirModel{[Required(ErrorMessage="Mevcut şifre zorunludur.")][DataType(DataType.Password)]public string MevcutSifre{get;set;}=string.Empty;[Required(ErrorMessage="Yeni şifre zorunludur.")][StringLength(100,MinimumLength=8,ErrorMessage="Yeni şifre en az 8 karakter olmalıdır.")][DataType(DataType.Password)]public string YeniSifre{get;set;}=string.Empty;[Required][Compare(nameof(YeniSifre),ErrorMessage="Yeni şifreler eşleşmiyor.")][DataType(DataType.Password)]public string YeniSifreTekrar{get;set;}=string.Empty;}
public sealed class AyarlarViewModel{public ProfilModel Profil{get;init;}=new();public SifreDegistirModel Sifre{get;init;}=new();}
